package com.opensocket.aievent.core.issuetracking.application.recovery;
import java.time.OffsetDateTime;import java.util.*;import java.util.concurrent.ConcurrentHashMap;import com.opensocket.aievent.core.issuetracking.recovery.*;
public final class InMemoryProjectionRecoveryRepository implements ProjectionRecoveryRepository {
 private final Map<String,OrderedProjectionLane> lanes=new ConcurrentHashMap<>();private final Map<String,OrderedProjectionWork> work=new ConcurrentHashMap<>();private final Map<String,ProjectionRecoveryCase> cases=new ConcurrentHashMap<>();private final Map<String,ProjectionReconciliationRun> runs=new ConcurrentHashMap<>();private final Map<String,ProviderHealthState> health=new ConcurrentHashMap<>();private final Map<String,List<ProjectionRecoveryEvent>> events=new ConcurrentHashMap<>();private String k(String t,String id){return t+"|"+id;}
 public OrderedProjectionLane saveLane(OrderedProjectionLane v){lanes.put(k(v.tenantId(),v.laneId()),v);return v;}public boolean saveLaneExpectedVersion(OrderedProjectionLane v,long e){return lanes.computeIfPresent(k(v.tenantId(),v.laneId()),(x,old)->old.version()==e?v:old).version()==v.version();}public Optional<OrderedProjectionLane> findLane(String t,String id){return Optional.ofNullable(lanes.get(k(t,id)));}public Optional<OrderedProjectionLane> findLaneByAggregate(String t,String key,ProjectionLaneType type){return lanes.values().stream().filter(v->v.tenantId().equals(t)&&v.aggregateKey().equals(key)&&v.laneType()==type).findFirst();}public List<OrderedProjectionLane> listLanes(String t,ProjectionLaneStatus s,int n){return lanes.values().stream().filter(v->v.tenantId().equals(t)&&(s==null||v.status()==s)).limit(n).toList();}
 public OrderedProjectionWork saveWork(OrderedProjectionWork v){work.put(k(v.tenantId(),v.workId()),v);return v;}public boolean saveWorkExpectedVersion(OrderedProjectionWork v,long e){var key=k(v.tenantId(),v.workId());var old=work.get(key);if(old==null||old.version()!=e)return false;work.put(key,v);return true;}public Optional<OrderedProjectionWork> findWork(String t,String id){return Optional.ofNullable(work.get(k(t,id)));}public List<OrderedProjectionWork> listWork(String t,String lane,ProjectionWorkStatus s,int n){return work.values().stream().filter(v->v.tenantId().equals(t)&&(lane==null||lane.isBlank()||v.laneId().equals(lane))&&(s==null||v.status()==s)).sorted(Comparator.comparingLong(OrderedProjectionWork::laneSequence)).limit(n).toList();}public List<OrderedProjectionWork> claimDueWork(String t,OffsetDateTime d,int n){return work.values().stream().filter(v->v.tenantId().equals(t)&&(v.status()==ProjectionWorkStatus.READY||v.status()==ProjectionWorkStatus.BLOCKED||v.status()==ProjectionWorkStatus.RETRY_WAITING||v.status()==ProjectionWorkStatus.RECOVERY_WAITING_INDEX)&&(v.nextAttemptAt()==null||!v.nextAttemptAt().isAfter(d))).filter(v->findLane(t,v.laneId()).map(l->l.status()==ProjectionLaneStatus.ACTIVE||l.status()==ProjectionLaneStatus.THROTTLED||l.status()==ProjectionLaneStatus.RECOVERING).orElse(false)).filter(v->work.values().stream().noneMatch(p->p.tenantId().equals(t)&&p.laneId().equals(v.laneId())&&p.generation()==v.generation()&&p.laneSequence()<v.laneSequence()&&!p.terminal())).filter(v->v.dependsOnWorkId()==null||v.dependsOnWorkId().isBlank()||findWork(t,v.dependsOnWorkId()).map(p->p.status()==ProjectionWorkStatus.ACKNOWLEDGED).orElse(false)).sorted(Comparator.comparing(OrderedProjectionWork::laneId).thenComparingLong(OrderedProjectionWork::generation).thenComparingLong(OrderedProjectionWork::laneSequence)).limit(n).toList();}public List<OrderedProjectionWork> listExpiredClaims(String t,OffsetDateTime d,int n){return work.values().stream().filter(v->v.tenantId().equals(t)&&(v.status()==ProjectionWorkStatus.CLAIMED||v.status()==ProjectionWorkStatus.IN_PROGRESS)&&(v.claimUntil()!=null&&!v.claimUntil().isAfter(d))).sorted(Comparator.comparing(OrderedProjectionWork::claimUntil)).limit(n).toList();}public List<OrderedProjectionWork> findCoalescible(String t,String lane,String key,long g,int n){return work.values().stream().filter(v->v.tenantId().equals(t)&&v.laneId().equals(lane)&&Objects.equals(v.coalesceKey(),key)&&v.generation()==g&&v.operationType()==ProjectionOperationType.UPDATE&&!v.terminal()).limit(n).toList();}
 public ProjectionRecoveryCase saveCase(ProjectionRecoveryCase v){cases.put(k(v.tenantId(),v.caseId()),v);return v;}public boolean saveCaseExpectedVersion(ProjectionRecoveryCase v,long e){var key=k(v.tenantId(),v.caseId());var old=cases.get(key);if(old==null||old.version()!=e)return false;cases.put(key,v);return true;}public Optional<ProjectionRecoveryCase> findCase(String t,String id){return Optional.ofNullable(cases.get(k(t,id)));}public Optional<ProjectionRecoveryCase> findOpenCase(String t,String w,ProjectionRecoveryCaseType type){return cases.values().stream().filter(v->v.tenantId().equals(t)&&Objects.equals(v.workId(),w)&&v.caseType()==type&&v.status()!=ProjectionRecoveryCaseStatus.RESOLVED&&v.status()!=ProjectionRecoveryCaseStatus.DEAD_LETTER&&v.status()!=ProjectionRecoveryCaseStatus.SUPERSEDED).findFirst();}public List<ProjectionRecoveryCase> listCases(String t,ProjectionRecoveryCaseStatus s,int n){return cases.values().stream().filter(v->v.tenantId().equals(t)&&(s==null||v.status()==s)).limit(n).toList();}
 public ProjectionReconciliationRun saveRun(ProjectionReconciliationRun v){runs.put(k(v.tenantId(),v.runId()),v);return v;}public boolean saveRunExpectedVersion(ProjectionReconciliationRun v,long e){var key=k(v.tenantId(),v.runId());var old=runs.get(key);if(old==null||old.version()!=e)return false;runs.put(key,v);return true;}public Optional<ProjectionReconciliationRun> findRun(String t,String id){return Optional.ofNullable(runs.get(k(t,id)));}public List<ProjectionReconciliationRun> listRuns(String t,ReconciliationRunStatus s,int n){return runs.values().stream().filter(v->v.tenantId().equals(t)&&(s==null||v.status()==s)).limit(n).toList();}
 public ProviderHealthState saveHealth(ProviderHealthState v){health.put(k(v.tenantId(),v.healthId()),v);return v;}public boolean saveHealthExpectedVersion(ProviderHealthState v,long e){var key=k(v.tenantId(),v.healthId());var old=health.get(key);if(old==null||old.version()!=e)return false;health.put(key,v);return true;}public Optional<ProviderHealthState> findHealth(String t,String c,String m){return health.values().stream().filter(v->v.tenantId().equals(t)&&v.connectionId().equals(c)&&Objects.equals(v.projectMappingId(),m==null?"":m)).findFirst();}public List<ProviderHealthState> listHealth(String t,ProviderHealthStatus s,int n){return health.values().stream().filter(v->v.tenantId().equals(t)&&(s==null||v.status()==s)).limit(n).toList();}
 public ProjectionRecoveryEvent appendEvent(ProjectionRecoveryEvent v){events.computeIfAbsent(k(v.tenantId(),v.aggregateType()+"|"+v.aggregateId()),x->new ArrayList<>()).add(v);return v;}public Optional<ProjectionRecoveryEvent> latestEvent(String t,String type,String id){var list=events.get(k(t,type+"|"+id));return list==null||list.isEmpty()?Optional.empty():Optional.of(list.get(list.size()-1));}public List<ProjectionRecoveryEvent> listEvents(String t,String type,String id,int n){var list=events.getOrDefault(k(t,type+"|"+id),List.of());return list.stream().sorted(Comparator.comparing(ProjectionRecoveryEvent::occurredAt).reversed()).limit(n).toList();}public String mode(){return "IN_MEMORY_TEST";}
}